static const char * const kKPConsoleHTML =
"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,user-scalable=no\">\n<title>LCProxy 控制台</title>\n<style>\n:root{\n  --bg:#0f1115; --panel:#171a21; --panel2:#1e222b; --border:#2a2f3a;\n  --fg:#e6e9ef; --dim:#8b93a3; --accent:#4f8cff; --ok:#3ecf8e; --bad:#ff5c5c;\n  --warn:#ffb454;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{background:var(--bg);color:var(--fg);font:14px/1.6 -apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;padding-bottom:60px}\nheader{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--border);background:var(--panel)}\nheader h1{font-size:17px;font-weight:600}\nheader .badge{margin-left:auto;font-size:12px;color:var(--dim)}\nnav{display:flex;gap:6px;padding:10px 16px;overflow-x:auto;border-bottom:1px solid var(--border);position:sticky;top:0;background:var(--bg);z-index:5}\nnav button{flex:0 0 auto;padding:8px 16px;border:1px solid var(--border);border-radius:8px;background:var(--panel);color:var(--dim);font-size:14px;cursor:pointer}\nnav button.active{background:var(--accent);color:#fff;border-color:var(--accent)}\nmain{padding:16px;max-width:860px;margin:0 auto}\n.tab{display:none}\n.tab.active{display:block}\n.card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:14px 16px;margin-bottom:14px}\n.card h2{font-size:15px;margin-bottom:10px;display:flex;align-items:center;gap:8px}\n.row{display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px dashed var(--border)}\n.row:last-child{border-bottom:none}\n.row .k{color:var(--dim)}\n.row .v{font-weight:500;word-break:break-all;text-align:right}\n.ok{color:var(--ok)} .bad{color:var(--bad)} .warn{color:var(--warn)} .dim{color:var(--dim)}\ninput[type=text],input[type=password],select{width:100%;padding:9px 10px;border:1px solid var(--border);border-radius:8px;background:var(--panel2);color:var(--fg);font-size:14px;margin:4px 0}\nbutton{appearance:none;border:1px solid var(--border);border-radius:8px;background:var(--panel2);color:var(--fg);padding:9px 14px;font-size:14px;cursor:pointer;margin:4px 4px 4px 0}\nbutton.primary{background:var(--accent);border-color:var(--accent);color:#fff}\nbutton.danger{background:transparent;border-color:var(--bad);color:var(--bad)}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n.switch{position:relative;width:46px;height:26px;display:inline-block}\n.switch input{opacity:0;width:0;height:0}\n.switch .slider{position:absolute;inset:0;background:var(--border);border-radius:13px;transition:.2s}\n.switch .slider:before{content:\"\";position:absolute;width:20px;height:20px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s}\n.switch input:checked + .slider{background:var(--ok)}\n.switch input:checked + .slider:before{transform:translateX(20px)}\n.steps{max-height:320px;overflow-y:auto;border:1px solid var(--border);border-radius:8px;padding:6px;background:var(--panel2);font-size:12px}\n.step{display:flex;gap:8px;padding:4px 6px;border-bottom:1px dashed var(--border)}\n.step:last-child{border-bottom:none}\n.step .t{color:var(--dim);flex:0 0 auto}\n.step .m{color:var(--accent);flex:0 0 auto}\n.step .n{flex:0 0 auto;font-weight:600}\n.step .d{color:var(--dim);flex:1}\n.msg{margin-top:8px;font-size:13px;min-height:20px}\npre{white-space:pre-wrap;word-break:break-all;font-size:12px;color:var(--dim);background:var(--panel2);border:1px solid var(--border);border-radius:8px;padding:10px;max-height:260px;overflow:auto}\nfooter{position:fixed;bottom:0;left:0;right:0;padding:8px 16px;background:var(--panel);border-top:1px solid var(--border);font-size:12px;color:var(--dim);display:flex;gap:10px}\n</style>\n</head>\n<body>\n<header>\n  <h1>🛰 LCProxy 控制台</h1>\n  <span class=\"badge\" id=\"hdrVer\">…</span>\n</header>\n<nav>\n  <button data-tab=\"status\" class=\"active\">状态</button>\n  <button data-tab=\"ts\">Tailscale</button>\n  <button data-tab=\"king\">出口代理</button>\n  <button data-tab=\"about\">关于</button>\n</nav>\n<main>\n\n<!-- ============ 状态 ============ -->\n<section class=\"tab active\" id=\"tab-status\">\n  <div class=\"card\">\n    <h2>Tailscale 核心</h2>\n    <div class=\"row\"><span class=\"k\">核心文件</span><span class=\"v\" id=\"st-corePresent\">…</span></div>\n    <div class=\"row\"><span class=\"k\">版本</span><span class=\"v\" id=\"st-coreVersion\">…</span></div>\n    <div class=\"row\"><span class=\"k\">运行状态</span><span class=\"v\" id=\"st-running\">…</span></div>\n    <div class=\"row\"><span class=\"k\">登录</span><span class=\"v\" id=\"st-needsLogin\">…</span></div>\n    <div class=\"row\"><span class=\"k\">当前用户</span><span class=\"v\" id=\"st-user\">…</span></div>\n    <div class=\"row\"><span class=\"k\">本机 IP</span><span class=\"v\" id=\"st-ips\">…</span></div>\n    <div class=\"row\"><span class=\"k\">DERP-only</span><span class=\"v\" id=\"st-derp\">…</span></div>\n    <div class=\"row\"><span class=\"k\">出口节点</span><span class=\"v\" id=\"st-exit\">…</span></div>\n  </div>\n  <div class=\"card\">\n    <h2>模式</h2>\n    <div class=\"row\"><span class=\"k\">当前模式</span><span class=\"v\" id=\"st-mode\">…</span></div>\n    <div class=\"row\"><span class=\"k\">Tailscale</span><span class=\"v\" id=\"st-ts\">…</span></div>\n    <div class=\"row\"><span class=\"k\">免流出口</span><span class=\"v\" id=\"st-king\">…</span></div>\n    <div class=\"row\"><span class=\"k\">期望 hook 代理</span><span class=\"v\" id=\"st-proxy\">…</span></div>\n  </div>\n  <div class=\"card\">\n    <h2>免流出口</h2>\n    <div class=\"row\"><span class=\"k\">转发器</span><span class=\"v\" id=\"st-kingRun\">…</span></div>\n    <div class=\"row\"><span class=\"k\">凭证(GUID)</span><span class=\"v\" id=\"st-guid\">…</span></div>\n    <div class=\"row\"><span class=\"k\">上次刷新</span><span class=\"v\" id=\"st-refresh\">…</span></div>\n    <div class=\"row\"><span class=\"k\">取号 / 登录 / 探活</span><span class=\"v\" id=\"st-kingChecks\">…</span></div>\n  </div>\n</section>\n\n<!-- ============ Tailscale ============ -->\n<section class=\"tab\" id=\"tab-ts\">\n  <div class=\"card\">\n    <h2>Tailscale 开关</h2>\n    <div class=\"row\"><span class=\"k\">启用 Tailscale</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"ts-enabled\"><span class=\"slider\"></span></label></div>\n    <div class=\"row\"><span class=\"k\">模式</span><span class=\"v\" id=\"ts-mode\">…</span></div>\n    <div class=\"msg dim\">开启后切到模式 A（+免流）或 B（仅 Tailscale）；core 会自动加载。免流联动时自动强制 DERP-only。</div>\n    <div class=\"msg dim\" id=\"ts-enablemsg\"></div>\n  </div>\n  <div class=\"card\">\n    <h2>登录</h2>\n    <input type=\"text\" id=\"ts-authkey\" placeholder=\"AuthKey（留空则输出登录 URL）\" autocomplete=\"off\">\n    <button class=\"primary\" id=\"btn-login\">登录</button>\n    <button class=\"danger\" id=\"btn-logout\">登出(清状态)</button>\n    <div class=\"msg dim\" id=\"ts-loginmsg\"></div>\n  </div>\n  <div class=\"card\">\n    <h2>核心更新</h2>\n    <div class=\"row\"><span class=\"k\">本地版本</span><span class=\"v\" id=\"up-local\">…</span></div>\n    <div class=\"row\"><span class=\"k\">最新版本</span><span class=\"v\" id=\"up-latest\">…</span></div>\n    <div class=\"row\"><span class=\"k\">更新源</span><span class=\"v\" id=\"up-repo\">…</span></div>\n    <button class=\"primary\" id=\"btn-check\">检查更新</button>\n    <button id=\"btn-download\">下载并安装(重启生效)</button>\n    <input type=\"text\" id=\"up-custom\" placeholder=\"自定义下载 URL（默认走 GitHub Release）\">\n    <button id=\"btn-download-custom\">自定义下载</button>\n    <div class=\"msg dim\" id=\"up-msg\"></div>\n  </div>\n  <div class=\"card\">\n    <h2>出口节点</h2>\n    <select id=\"ts-exitnodes\"><option value=\"\">加载中…</option></select>\n    <button class=\"primary\" id=\"btn-exit-apply\">应用</button>\n    <button id=\"btn-exit-clear\">清除</button>\n    <div class=\"msg dim\" id=\"ts-exitmsg\"></div>\n  </div>\n  <div class=\"card\">\n    <h2>诊断</h2>\n    <div class=\"row\"><span class=\"k\">Ping 目标(100.x)</span><span class=\"v\" style=\"text-align:right\"><input type=\"text\" id=\"ts-pingip\" placeholder=\"100.x.y.z\" style=\"width:160px\"></span></div>\n    <button id=\"btn-ping\">Ping(disco)</button>\n    <button id=\"btn-netcheck\">Netcheck</button>\n    <div class=\"msg dim\" id=\"ts-diagmsg\"></div>\n    <pre id=\"ts-diagout\" style=\"display:none\"></pre>\n  </div>\n  <div class=\"card\">\n    <h2>偏好</h2>\n    <div class=\"row\"><span class=\"k\">RouteAll（接收子网路由）</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"ts-routeall\"><span class=\"slider\"></span></label></div>\n    <button id=\"btn-routeall\">保存 RouteAll</button>\n    <div class=\"msg dim\" id=\"ts-prefsmsg\"></div>\n  </div>\n</section>\n\n<!-- ============ 出口代理 ============ -->\n<section class=\"tab\" id=\"tab-king\">\n  <div class=\"card\">\n    <h2>免流出口</h2>\n    <div class=\"row\"><span class=\"k\">启用免流</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"kg-enabled\"><span class=\"slider\"></span></label></div>\n    <div class=\"row\"><span class=\"k\">Tailscale 联动</span><span class=\"v\" id=\"kg-link\">…</span></div>\n    <div class=\"msg dim\" id=\"kg-msg\"></div>\n  </div>\n  <div class=\"card\">\n    <h2>凭证（自动取号）</h2>\n    <div class=\"row\"><span class=\"k\">GUID</span><span class=\"v\" id=\"kg-guid\">…</span></div>\n    <div class=\"row\"><span class=\"k\">取号(kingcard)</span><span class=\"v\" id=\"kg-fetch\">…</span></div>\n    <div class=\"row\"><span class=\"k\">登录激活</span><span class=\"v\" id=\"kg-login\">…</span></div>\n    <div class=\"row\"><span class=\"k\">探活(generate_204)</span><span class=\"v\" id=\"kg-probe\">…</span></div>\n    <div class=\"msg dim\">取号=拿 GUID/TOKEN；登录激活=向免流网关注册会话；探活=验证真免流(204 即通)</div>\n    <div class=\"row\"><span class=\"k\">上次刷新</span><span class=\"v\" id=\"kg-refresh\">…</span></div>\n    <div class=\"row\"><span class=\"k\">刷新来源/次数</span><span class=\"v\" id=\"kg-source\">…</span></div>\n    <div class=\"row\"><span class=\"k\">取号路由</span><span class=\"v\" id=\"kg-route\">…</span></div>\n    <div class=\"row\"><span class=\"k\">上游</span><span class=\"v\" id=\"kg-upstream\">…</span></div>\n    <button id=\"btn-kg-refresh\">立即刷新凭证</button>\n    <details style=\"margin-top:6px\"><summary class=\"dim\">手动覆盖凭证（可选）</summary>      <input type=\"text\" id=\"kg-guid-input\" placeholder=\"GUID（留空=自动）\" autocomplete=\"off\">\n      <input type=\"password\" id=\"kg-token-input\" placeholder=\"TOKEN（留空=自动）\">\n      <button id=\"btn-kg-override\">保存覆盖</button>\n    </details>\n  </div>\n  <div class=\"card\">\n    <h2>DERP-only（仅中继）</h2>\n    <div class=\"row\"><span class=\"k\">状态</span><span class=\"v\" id=\"kg-derp\">…</span></div>\n    <div class=\"msg dim\">免流开启时自动强制 DERP-only（禁 P2P/打洞）；切换会短暂断连。</div>\n    <div class=\"card\">\n      <h2>出口 IP 测试</h2>\n      <div class=\"row\"><span class=\"k\">当前出口 IP</span><span class=\"v\" id=\"kg-ip\">…</span></div>\n      <div class=\"row\"><span class=\"k\">检测时间</span><span class=\"v\" id=\"kg-ipat\">…</span></div>\n      <button id=\"btn-ipcheck\">测试出口 IP（经免流网关）</button>\n      <div class=\"msg dim\">经免流网关访问 IP 服务的结果。刷新后变化=走了代理；不变或失败=直连/网关不通。</div>\n      <div class=\"msg dim\" id=\"kg-ipmsg\"></div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ 关于 ============ -->\n<section class=\"tab\" id=\"tab-about\">\n  <div class=\"card\">\n    <h2>关于</h2>\n    <div class=\"row\"><span class=\"k\">Tweak 版本</span><span class=\"v\" id=\"ab-tweak\">…</span></div>\n    <div class=\"row\"><span class=\"k\">Core 版本</span><span class=\"v\" id=\"ab-core\">…</span></div>\n    <div class=\"row\"><span class=\"k\">日志文件</span><span class=\"v\" id=\"ab-logfile\">…</span></div>\n    <div class=\"row\"><span class=\"k\">调试模式</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"ab-debug-switch\"><span class=\"slider\"></span></label></div>\n    <div class=\"row\"><span class=\"k\">日志级别</span><span class=\"v\" id=\"ab-loglevel\">…</span></div>\n    <div class=\"msg dim\" id=\"ab-debugmsg\"></div>\n    <p class=\"dim\" style=\"margin-top:8px\">\n      LCProxyTweak：LiveContainer 容器内 App 全量流量走 Tailscale / 王卡免流。\n      四模式：A(tailscale+免流) / B(tailscale) / C(纯免流) / D(全关)。\n      日志位于 Documents/KingProxy/logs/，每次启动一个新文件，最多保留 50 个。\n    </p>\n  </div>\n  <div class=\"card\">\n    <h2>调试 · 启动步骤验证</h2>\n    <button id=\"btn-steps-refresh\">刷新步骤</button>\n    <div class=\"msg dim\">每步 ✓/✗：boot → config → mode → king → tscore → web</div>\n    <div class=\"steps\" id=\"ab-steps\"><div class=\"dim\">加载中…</div></div>\n  </div>\n</section>\n\n</main>\n<footer>\n  <span id=\"ft-status\">…</span>\n  <span style=\"flex:1\"></span>\n  <span id=\"ft-time\"></span>\n</footer>\n\n<script>\n\"use strict\";\nconst $=id=>document.getElementById(id);\nlet state={};\n\nasync function api(path,opts){\n  const r=await fetch(path,{headers:{\"Content-Type\":\"application/json\"},...opts});\n  let j=null; try{j=await r.json()}catch(e){}\n  if(!r.ok) return {error:(j&&(j.error||j.message))||(\"HTTP \"+r.status)};\n  return j;\n}\nfunction fmtBool(b){return b?\"<span class='ok'>✓ 是</span>\":\"<span class='bad'>✗ 否</span>\";}\nfunction fmtState(s){return s===\"✓\"?\"<span class='ok'>✓</span>\":(s===\"✗\"?\"<span class='bad'>✗</span>\":(s===\"?\"?\"<span class='dim'>?</span>\":\"<span class='warn'>\"+s+\"</span>\"));}\n\n// ---------- 状态 ----------\nasync function loadStatus(){\n  const st=await api(\"/api/status\");\n  if(st.error){$(\"ft-status\").textContent=\"状态获取失败: \"+st.error;return;}\n  state.status=st;\n  $(\"st-corePresent\").innerHTML=st.core.present?fmtBool(true):\"<span class='bad'>未安装</span>\";\n  $(\"st-coreVersion\").textContent=st.core.version||\"—\";\n  $(\"st-running\").innerHTML=st.core.running?fmtBool(true):\"<span class='bad'>未运行</span>\";\n  $(\"st-needsLogin\").innerHTML=st.core.needsLogin?(\"<span class='bad'>需要登录</span>\"):fmtBool(true);\n  $(\"st-user\").textContent=st.core.currentUser||\"—\";\n  $(\"st-ips\").textContent=(st.core.tailscaleIPs||[]).join(\", \")||\"—\";\n  $(\"st-derp\").textContent=st.derpOnly?\"<span class='ok'>开启(仅中继)</span>\":\"关闭\";\n  $(\"st-exit\").textContent=st.exitNode&&st.exitNode.name?st.exitNode.name:\"—\";\n  $(\"st-mode\").textContent=st.mode;\n  $(\"st-ts\").innerHTML=fmtBool(st.tailscaleEnabled);\n  $(\"st-king\").innerHTML=fmtBool(st.kingEnabled);\n  $(\"st-proxy\").textContent=st.desiredProxy||\"—\";\n  $(\"st-kingRun\").innerHTML=st.king.running?fmtBool(true):\"<span class='bad'>停止</span>\";\n  $(\"st-guid\").textContent=st.king.guidMasked||\"—\";\n  $(\"st-refresh\").textContent=st.king.lastRefresh||\"—\";\n  $(\"st-kingChecks\").innerHTML=\n    \"取号\"+fmtState(st.king.lastFetchOk===true?\"✓\":(st.king.lastFetchOk===false?\"✗\":\"?\"))+\n    \" 登录\"+fmtState(st.king.lastLoginOk===true?\"✓\":(st.king.lastLoginOk===false?\"✗\":\"?\"))+\n    \" 探活\"+fmtState(st.king.probeOk===true?\"✓\":(st.king.probeOk===false?\"✗\":\"?\"));\n  $(\"kg-enabled\").checked=!!st.kingEnabled;\n  $(\"ts-enabled\").checked=!!st.tailscaleEnabled;\n  $(\"ts-mode\").textContent=st.mode;\n  $(\"kg-guid\").textContent=st.king.guidMasked||\"—\";\n  $(\"kg-fetch\").innerHTML=fmtState(st.king.lastFetchOk===true?\"✓\":(st.king.lastFetchOk===false?\"✗\":\"?\"));\n  $(\"kg-login\").innerHTML=fmtState(st.king.lastLoginOk===true?\"✓\":(st.king.lastLoginOk===false?\"✗\":\"?\"));\n  $(\"kg-probe\").innerHTML=st.king.probeRan?fmtState(st.king.probeOk?\"✓\":\"✗\"):\"<span class='dim'>— 未执行</span>\";\n  $(\"kg-refresh\").textContent=st.king.lastRefresh||\"—\";\n  $(\"kg-source\").textContent=(st.king.lastRefreshSource||\"—\")+\" × \"+(st.king.refreshCount||0);\n  $(\"kg-route\").textContent=st.king.lastFetchRoute||\"—\";\n  $(\"kg-upstream\").textContent=st.king.upstream||\"—\";\n  $(\"kg-link\").textContent=st.kingEnabled?\"免流开 → 强制 DERP-only\":\"—\";\n  $(\"kg-derp\").textContent=st.derpOnly?\"<span class='ok'>DERP-only 开启</span>\":\"P2P 允许\";\n  $(\"ft-status\").textContent=\"已连接 · 模式 \"+st.mode;\n  $(\"hdrVer\").textContent=\"tweak \"+st.tweakVersion+(st.core.version?\" · core \"+st.core.version:\"\");\n}\n\n// ---------- 关于 / 调试 ----------\nasync function loadAbout(){\n  const v=await api(\"/api/version\");\n  if(!v.error){$(\"ab-tweak\").textContent=v.tweakVersion; $(\"ab-core\").textContent=v.coreVersion||\"—\";}\n  const d=await api(\"/api/debug\");\n  if(!d.error){\n    $(\"ab-debug-switch\").checked=!!d.debugEnabled;\n    $(\"ab-loglevel\").textContent=d.logLevel||\"—\";\n    $(\"ab-logfile\").textContent=d.logFile||\"—\";\n    renderSteps(d.steps||[]);\n  }\n}\n\n$(\"ab-debug-switch\").onchange=async e=>{\n  const r=await api(\"/api/debug\",{method:\"POST\",body:JSON.stringify({enabled:e.target.checked})});\n  $(\"ab-debugmsg\").textContent=r.error?(\"失败: \"+r.error):(e.target.checked?\"调试模式已开启（日志级别 debug）\":\"调试模式已关闭（日志级别 info）\");\n  loadAbout();\n};\nfunction renderSteps(steps){\n  const box=$(\"ab-steps\");\n  if(!steps.length){box.innerHTML=\"<div class='dim'>暂无步骤记录</div>\";return;}\n  box.innerHTML=steps.map(s=>\n    \"<div class='step'><span class='t'>\"+s.t.slice(11,23)+\"</span>\"+\n    \"<span class='m'>[\"+s.module+\"]</span>\"+\n    \"<span class='n'>\"+(s.ok?\"✓\":\"✗\")+\" \"+escapeHtml(s.name)+\"</span>\"+\n    \"<span class='d'>\"+escapeHtml(s.detail)+\"</span></div>\"\n  ).join(\"\");\n}\nfunction escapeHtml(s){return String(s).replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));}\n\n// ---------- 交互 ----------\ndocument.querySelectorAll(\"nav button\").forEach(b=>b.onclick=()=>{\n  document.querySelectorAll(\"nav button\").forEach(x=>x.classList.remove(\"active\"));\n  document.querySelectorAll(\".tab\").forEach(x=>x.classList.remove(\"active\"));\n  b.classList.add(\"active\");\n  $(\"tab-\"+b.dataset.tab).classList.add(\"active\");\n  if(b.dataset.tab===\"status\")loadStatus();\n  if(b.dataset.tab===\"king\")loadStatus();\n  if(b.dataset.tab===\"about\")loadAbout();\n});\n\n$(\"kg-enabled\").onchange=async e=>{\n  const r=await api(\"/api/king\",{method:\"POST\",body:JSON.stringify({enabled:e.target.checked})});\n  $(\"kg-msg\").textContent=r.error?(\"失败: \"+r.error):\"已保存，重新应用模式\";\n  loadStatus();\n};\n\n$(\"ts-enabled\").onchange=async e=>{\n  $(\"ts-enablemsg\").textContent=\"保存中…\";\n  const r=await api(\"/api/tailscale\",{method:\"POST\",body:JSON.stringify({enabled:e.target.checked})});\n  $(\"ts-enablemsg\").textContent=r.error?(\"失败: \"+r.error):\"已保存，重新应用模式\";\n  loadStatus();\n};\n\n$(\"btn-kg-refresh\").onclick=async()=>{\n  $(\"kg-msg\").textContent=\"刷新中…\";\n  const r=await api(\"/api/king/refresh\",{method:\"POST\"});\n  $(\"kg-msg\").textContent=r.error?(\"失败: \"+r.error):\"刷新完成\";\n  loadStatus();\n};\n\n$(\"btn-ipcheck\").onclick=async()=>{\n  $(\"kg-ipmsg\").textContent=\"检测中(经免流网关)…\";\n  const r=await api(\"/api/ipcheck\");\n  if(r.error){\n    $(\"kg-ipmsg\").textContent=\"失败: \"+r.error;\n  }else{\n    $(\"kg-ip\").textContent=r.ip;\n    $(\"kg-ipat\").textContent=r.at||\"\";\n    $(\"kg-ipmsg\").textContent=\"经免流网关出口 IP（直连对比：关免流后再测一次）\";\n  }\n};\n\n$(\"btn-kg-override\").onclick=async()=>{\n  const r=await api(\"/api/king\",{method:\"POST\",body:JSON.stringify({guid:$(\"kg-guid-input\").value||null,token:$(\"kg-token-input\").value||null})});\n  $(\"kg-msg\").textContent=r.error?(\"失败: \"+r.error):\"覆盖凭证已保存\";\n  loadStatus();\n};\n\n$(\"btn-login\").onclick=async()=>{\n  const st=state.status||{};\n  if(!st.tailscaleEnabled){\n    $(\"ts-loginmsg\").textContent=\"请先在上方打开「启用 Tailscale」开关（切到模式 A/B）再登录\";\n    return;\n  }\n  if(st.core&&!st.core.present){\n    $(\"ts-loginmsg\").textContent=\"core 未安装：请先下载并安装 TailscaleCore（本页核心更新）\";\n    return;\n  }\n  const key=$(\"ts-authkey\").value.trim();\n  $(\"ts-loginmsg\").textContent=key?\"登录中(≤2分钟)…\":\"获取登录 URL…\";\n  const r=await api(\"/api/login\",{method:\"POST\",body:JSON.stringify({authkey:key})});\n  $(\"ts-loginmsg\").textContent=r.error?(\"失败: \"+r.error):(r.loginURL?(\"请用浏览器打开: \"+r.loginURL):\"登录完成\");\n  loadStatus();\n};\n\n$(\"btn-logout\").onclick=async()=>{\n  const r=await api(\"/api/logout\",{method:\"POST\"});\n  $(\"ts-loginmsg\").textContent=r.error?(\"失败: \"+r.error):\"已登出\";\n  loadStatus();\n};\n\n$(\"btn-check\").onclick=async()=>{\n  $(\"up-msg\").textContent=\"检查中…\";\n  const r=await api(\"/api/core/check\");\n  $(\"up-latest\").textContent=r.latestVersion||\"—\";\n  $(\"up-msg\").textContent=r.error?(\"失败: \"+r.error):(\"最新: \"+(r.latestVersion||\"—\")+(r.upToDate?\"（已是最新）\":\"\"));\n};\n\n$(\"btn-download\").onclick=async()=>{\n  $(\"up-msg\").textContent=\"下载中…\";\n  const r=await api(\"/api/core/download\",{method:\"POST\",body:JSON.stringify({})});\n  $(\"up-msg\").textContent=r.error?(\"失败: \"+r.error):(\"下载完成: \"+r.message);\n};\n\n$(\"btn-download-custom\").onclick=async()=>{\n  const url=$(\"up-custom\").value.trim();\n  if(!url){$(\"up-msg\").textContent=\"请输入自定义 URL\";return;}\n  $(\"up-msg\").textContent=\"下载中…\";\n  const r=await api(\"/api/core/download\",{method:\"POST\",body:JSON.stringify({url})});\n  $(\"up-msg\").textContent=r.error?(\"失败: \"+r.error):(\"下载完成: \"+r.message);\n};\n\n$(\"btn-exit-apply\").onclick=async()=>{\n  const id=$(\"ts-exitnodes\").value;\n  if(!id){$(\"ts-exitmsg\").textContent=\"请选择节点\";return;}\n  const r=await api(\"/api/exitnode\",{method:\"POST\",body:JSON.stringify({id})});\n  $(\"ts-exitmsg\").textContent=r.error?(\"失败: \"+r.error):\"已应用\";\n  loadStatus();\n};\n$(\"btn-exit-clear\").onclick=async()=>{\n  const r=await api(\"/api/exitnode/clear\",{method:\"POST\"});\n  $(\"ts-exitmsg\").textContent=r.error?(\"失败: \"+r.error):\"已清除\";\n  loadStatus();\n};\n\nasync function loadExitNodes(){\n  const r=await api(\"/api/exitnodes\");\n  if(r.error){$(\"ts-exitnodes\").innerHTML=\"<option>加载失败: \"+r.error+\"</option>\";return;}\n  const list=r.nodes||[];\n  $(\"ts-exitnodes\").innerHTML=list.length?\n    list.map(n=>\"<option value='\"+n.id+\"'>\"+(n.countryCode?(\"[\"+n.countryCode+\"] \"):\"\")+n.name+(n.online?\"\":\"(离线)\")+\"</option>\").join(\"\"):\n    \"<option value=''>暂无可用出口节点（需 core 运行且在线）</option>\";\n}\n\n$(\"btn-ping\").onclick=async()=>{\n  const ip=$(\"ts-pingip\").value.trim();\n  if(!ip){$(\"ts-diagmsg\").textContent=\"请输入目标 IP\";return;}\n  $(\"ts-diagmsg\").textContent=\"Ping 中…\";\n  const r=await api(\"/api/ping\",{method:\"POST\",body:JSON.stringify({ip,type:\"disco\"})});\n  $(\"ts-diagmsg\").textContent=r.error?(\"失败: \"+r.error):\"完成\";\n  $(\"ts-diagout\").style.display=\"block\";\n  $(\"ts-diagout\").textContent=JSON.stringify(r.result||r,null,2);\n};\n$(\"btn-netcheck\").onclick=async()=>{\n  $(\"ts-diagmsg\").textContent=\"Netcheck 中…\";\n  const r=await api(\"/api/netcheck\",{method:\"POST\"});\n  $(\"ts-diagmsg\").textContent=r.error?(\"失败: \"+r.error):\"完成\";\n  $(\"ts-diagout\").style.display=\"block\";\n  $(\"ts-diagout\").textContent=JSON.stringify(r.result||r,null,2);\n};\n\n$(\"btn-routeall\").onclick=async()=>{\n  const r=await api(\"/api/prefs\",{method:\"POST\",body:JSON.stringify({routeAll:$(\"ts-routeall\").checked})});\n  $(\"ts-prefsmsg\").textContent=r.error?(\"失败: \"+r.error):\"已保存\";\n};\n\n$(\"btn-steps-refresh\").onclick=loadAbout;\n\n// ---------- 轮询 ----------\nsetInterval(()=>{\n  const active=document.querySelector(\"nav button.active\").dataset.tab;\n  if(active===\"status\")loadStatus();\n},3000);\nsetInterval(()=>{$(\"ft-time\").textContent=new Date().toLocaleTimeString();},1000);\n\n// 初始\nloadStatus(); loadAbout(); loadExitNodes();\n</script>\n</body>\n</html>\n";
